update public.exercises set consigne = '<p>Vous êtes étudiant(e) et vous vous sentez très stressé(e) en période d''examens. Vous cherchez une activité pour vous détendre en fonction des critères suivants :</p><p>• le soir, après les cours ;<br>• gratuite ;<br>• sans inscription à l''avance ;<br>• avec d''autres personnes.</p><p>Vous comparez ces quatre annonces. Pour chaque annonce, cochez (☒) OUI si cela correspond au critère ou NON si cela ne correspond pas.</p>', reading_text = null where id = 'lo22mvemxyoo02c';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"lo22mvemxyoo02cc1","titre":"Yoga au parc","texte":"<p>Le dimanche matin à 10 h, l''association Souffle et Détente vous donne rendez-vous sur la grande pelouse du parc pour une heure de yoga en plein air. Débutants et habitués pratiquent côte à côte, dans une ambiance détendue. Pas besoin de réserver ni de payer quoi que ce soit : il suffit d''arriver un peu en avance avec son tapis et une bouteille d''eau. En cas de pluie, la séance est annulée et un message est publié le matin même sur la page de l''association. Après la séance, beaucoup de participants prolongent le moment autour d''un café au kiosque.</p>"},{"id":"lo22mvemxyoo02cc2","titre":"Groupe de parole étudiant","texte":"<p>Examens, solitude, vie loin de sa famille : il n''est pas toujours facile d''en parler. Le jeudi à 19 h, à la maison des étudiants, une psychologue anime un temps d''échange où chacun peut partager ce qu''il vit, ou simplement écouter les autres. Pour garantir la qualité des échanges, chaque groupe est limité à huit personnes, et il faut réserver sa place au moins une semaine à l''avance par courriel. La participation est entièrement prise en charge par l''université. Ce qui se dit pendant la séance reste confidentiel, et personne n''est obligé de prendre la parole.</p>"},{"id":"lo22mvemxyoo02cc3","titre":"Piscine du campus","texte":"<p>Envie de vous vider la tête entre deux révisions ? La piscine du campus ouvre ses bassins aux étudiants du lundi au vendredi, de 12 h à 14 h. Inutile de réserver : présentez simplement votre carte d''étudiant à l''accueil. L''entrée coûte 2 €, et une carte de dix entrées est proposée à 15 €. Ici, pas de cours collectif ni d''animation : chaque nageur dispose de son couloir et nage à son rythme, dans le calme. Des serviettes et des bonnets de bain sont en vente à l''accueil pour ceux qui les auraient oubliés.</p>"},{"id":"lo22mvemxyoo02cc4","titre":"Chorale du quartier","texte":"<p>Chaque lundi à 20 h, une trentaine d''habitants du quartier se retrouvent à la salle des fêtes pour chanter ensemble des chansons françaises et des airs du monde entier. Aucun niveau n''est demandé, et il n''est pas nécessaire de savoir lire la musique : la cheffe de chœur apprend les chants à l''oreille. Vous pouvez venir découvrir l''ambiance à n''importe quelle répétition, sans prévenir personne. Si vous décidez de rester, l''adhésion coûte 40 € pour l''année, partitions comprises. Deux concerts sont donnés chaque année, mais personne n''est obligé d''y participer.</p>"}],"criteres":[{"id":"lo22mvemxyoo02ct1","texte":"Horaires"},{"id":"lo22mvemxyoo02ct2","texte":"Prix"},{"id":"lo22mvemxyoo02ct3","texte":"Inscription"},{"id":"lo22mvemxyoo02ct4","texte":"Groupe"}]}'::jsonb, '{"answers":{"lo22mvemxyoo02ct1_lo22mvemxyoo02cc1":"NON","lo22mvemxyoo02ct2_lo22mvemxyoo02cc1":"OUI","lo22mvemxyoo02ct3_lo22mvemxyoo02cc1":"OUI","lo22mvemxyoo02ct4_lo22mvemxyoo02cc1":"OUI","lo22mvemxyoo02ct1_lo22mvemxyoo02cc2":"OUI","lo22mvemxyoo02ct2_lo22mvemxyoo02cc2":"OUI","lo22mvemxyoo02ct3_lo22mvemxyoo02cc2":"NON","lo22mvemxyoo02ct4_lo22mvemxyoo02cc2":"OUI","lo22mvemxyoo02ct1_lo22mvemxyoo02cc3":"NON","lo22mvemxyoo02ct2_lo22mvemxyoo02cc3":"NON","lo22mvemxyoo02ct3_lo22mvemxyoo02cc3":"OUI","lo22mvemxyoo02ct4_lo22mvemxyoo02cc3":"NON","lo22mvemxyoo02ct1_lo22mvemxyoo02cc4":"OUI","lo22mvemxyoo02ct2_lo22mvemxyoo02cc4":"NON","lo22mvemxyoo02ct3_lo22mvemxyoo02cc4":"OUI","lo22mvemxyoo02ct4_lo22mvemxyoo02cc4":"OUI"}}'::jsonb, 'Yoga au parc: « Le dimanche matin à 10 h » (NON), « ni de payer quoi que ce soit » (OUI), « Pas besoin de réserver » (OUI), « Débutants et habitués pratiquent côte à côte » (OUI). Groupe de parole étudiant: « Le jeudi à 19 h » (OUI), « entièrement prise en charge par l''université » (OUI), « il faut réserver sa place au moins une semaine à l''avance » (NON), « chaque groupe est limité à huit personnes » (OUI). Piscine du campus: « de 12 h à 14 h » (NON), « L''entrée coûte 2 € » (NON), « Inutile de réserver » (OUI), « chaque nageur dispose de son couloir et nage à son rythme » (NON). Chorale du quartier: « Chaque lundi à 20 h » (OUI), « l''adhésion coûte 40 € pour l''année » (NON), « sans prévenir personne » (OUI), « une trentaine d''habitants du quartier se retrouvent » (OUI).')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemxyoo02c' and q.ord = v.ord;
