-- lo22mvemxyoo02d
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>', reading_text = '<p><strong>Santé mentale des jeunes : une grande cause qui doit encore faire ses preuves</strong></p><p>En 2025, la santé mentale avait été déclarée « grande cause nationale » en France. Fin novembre 2025, le gouvernement a annoncé qu''elle le resterait en 2026, en promettant cette fois des actions plus concrètes. Cette décision répondait notamment à une demande des hôpitaux publics, qui souhaitaient que l''effort porte en priorité sur les jeunes. Reconduire un label, cependant, ne coûte rien ; c''est à ce qui suit qu''on juge une politique.</p><p>Les chiffres expliquent l''inquiétude des soignants. Selon une étude de Santé publique France menée auprès de 17 000 jeunes, environ un tiers des 11 à 24 ans présente des signes de détresse anxieuse ou dépressive, de modérée à sévère. Les hôpitaux constatent par ailleurs que les jeunes de 5 à 19 ans ont été beaucoup plus nombreux que prévu à être hospitalisés pour des troubles psychiatriques en 2024. Derrière ces pourcentages, il y a des familles qui attendent, parfois longtemps, une réponse qui ne vient pas.</p><p>Car l''offre de soins ne suit pas. Les services de psychiatrie sont saturés, de nombreux postes ne sont pas pourvus, et beaucoup de patients disent avoir déjà renoncé à un rendez-vous faute de place. Ce renoncement est sans doute le plus préoccupant : un jeune qui a trouvé le courage de demander de l''aide et qui se heurte à une porte fermée risque de ne pas frapper une deuxième fois. Chaque mois d''attente compte, surtout à un âge où les difficultés peuvent vite s''aggraver. Des députés ont d''ailleurs regretté que les mesures avancent trop lentement.</p><p>Quelques changements concrets arrivent malgré tout. Depuis le 1er octobre 2026, les patients du dispositif « Mon soutien psy » n''ont plus à avancer les frais chez le psychologue, ce qui supprime un obstacle financier réel pour les plus modestes. Les étudiants, eux, peuvent toujours bénéficier de séances gratuites. Pour les spécialistes, ces aides sont utiles, mais elles ne remplacent pas un vrai plan pour former et recruter des soignants. Faciliter l''accès à un psychologue n''a guère de sens, rappellent-ils, si les professionnels manquent pour recevoir ceux qui en ont besoin. Autrement dit, ouvrir la porte ne suffit pas ; encore faut-il que quelqu''un attende derrière. C''est sur ce point que les prochains mois diront si la grande cause en était vraiment une.</p><p><p><small><em>Texte rédigé par FRACILE à partir de : Fédération hospitalière de France, lettre ouverte, 27 novembre 2025 (fhf.fr) ; CIDJ, « Ce qui change en octobre 2026 », 1er octobre 2026 (cidj.com) ; Pourquoi Docteur, « Santé mentale, grande cause nationale 2026 » (pourquoidocteur.fr).</em></small></p></p>' where id = 'lo22mvemxyoo02d';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Selon l''auteur, reconduire la « grande cause nationale »…', '{"options":["ne suffit pas à juger une politique.","a été critiqué par les hôpitaux publics.","a coûté très cher à l''État."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« Reconduire un label, cependant, ne coûte rien ; c''est à ce qui suit qu''on juge une politique ».'),
  (2, 'qcm', 'Qu''avaient demandé les hôpitaux publics ?', '{"options":["que la grande cause soit abandonnée","que les étudiants paient moins cher","que les jeunes soient la priorité"],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, '« qui souhaitaient que l''effort porte en priorité sur les jeunes ».'),
  (3, 'qcm', 'D''après l''étude de Santé publique France,…', '{"options":["environ un jeune sur trois montre des signes de détresse.","17 000 jeunes souffrent d''une dépression grave et durable.","la moitié des jeunes a déjà été hospitalisée."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« environ un tiers des 11 à 24 ans présente des signes de détresse anxieuse ou dépressive ». 17 000 là số người được khảo sát.'),
  (4, 'vf', 'En 2024, les jeunes hospitalisés pour des troubles psychiatriques ont été moins nombreux que prévu.', '{"heSo":5}'::jsonb, '{"answer":1,"justification":"ont été beaucoup plus nombreux que prévu à être hospitalisés"}'::jsonb, null),
  (5, 'qcm', 'Pourquoi l''auteur juge-t-il le renoncement aux soins particulièrement grave ?', '{"options":["Les rendez-vous non honorés font perdre beaucoup d''argent aux hôpitaux.","Les familles portent plainte contre les services.","Un jeune refusé une fois risque de ne plus demander d''aide."],"heSo":4}'::jsonb, '{"answer":2}'::jsonb, '« un jeune qui a trouvé le courage de demander de l''aide et qui se heurte à une porte fermée risque de ne pas frapper une deuxième fois ».'),
  (6, 'qcm', 'Qu''ont reproché des députés ?', '{"options":["la lenteur des mesures","le manque de chiffres fiables","le coût des séances gratuites"],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« Des députés ont d''ailleurs regretté que les mesures avancent trop lentement ».'),
  (7, 'vf', 'Depuis le 1er octobre 2026, les patients de « Mon soutien psy » ne paient plus les frais à l''avance.', '{"heSo":5}'::jsonb, '{"answer":0,"justification":"n''ont plus à avancer les frais chez le psychologue"}'::jsonb, null),
  (8, 'qcm', 'Quelle limite les spécialistes voient-ils dans les nouvelles aides ?', '{"options":["Elles ne concernent que les étudiants.","Elles ne règlent pas le manque de soignants.","Elles coûtent trop cher à la Sécurité sociale."],"heSo":4}'::jsonb, '{"answer":1}'::jsonb, '« elles ne remplacent pas un vrai plan pour former et recruter des soignants ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
